#!/usr/bin/env node
import assert from 'node:assert/strict'; import {createHash} from 'node:crypto'; import {readFileSync} from 'node:fs'; import {resolve} from 'node:path'
const read=p=>JSON.parse(readFileSync(resolve(process.cwd(),p),'utf8')); const stable=v=>Array.isArray(v)?`[${v.map(stable).join(',')}]`:v&&typeof v==='object'?`{${Object.keys(v).sort().map(k=>`${JSON.stringify(k)}:${stable(v[k])}`).join(',')}}`:JSON.stringify(v); const sha=v=>`sha256:${createHash('sha256').update(stable(v)).digest('hex')}`
const b=read('reports/genesis-p5-claude-audit-bundle.json'); assert.equal(b.bundleId,'genesis-p5-claude-audit-bundle-v1'); assert.deepEqual(b.counts,{baseItems:24,candidateUnits:27,nodePairs:150,riskTiers:{R0:0,R1:10,R2:7,R3:5,R4:5}}); assert.equal(b.goldenControlExcluded,'H776'); assert.equal(b.records.length,27); assert.equal(new Set(b.records.map(r=>r.sourceStrong)).size,27); assert.equal(b.records.some(r=>r.baseStrong==='H776'||r.sourceStrong==='H776'),false); for(const r of b.records){assert.equal(r.auditContract.sourceMutationAllowed,false);assert.equal(r.auditContract.candidateMutationAllowed,false);assert.equal(r.auditContract.approvalRegistryWriteAllowed,false);assert.equal(r.auditContract.productionWriteAllowed,false);assert.ok(['R0','R1','R2','R3','R4'].includes(r.risk.tier)); for(const [i,p] of r.pairs.entries()){assert.equal(p.order,i+1);assert.ok(p.sourceText.trim());assert.ok(/[가-힣]/u.test(p.textKo));}} for(const k of ['approvalRegistryWriteAllowed','serviceUiWriteAllowed','productionWriteAllowed','existingApprovedMeaningMutationAllowed'])assert.equal(b.governance[k],false); const fp=b.bundleFingerprint; delete b.bundleFingerprint; assert.equal(fp,sha(b)); console.log('✓ Claude audit bundle verified · 27 units · 150 source/candidate pairs')
